\label{thm:m=0} For every integer $n$, there
is a rainbow--free $3$--coloring of $\mbox{${\mathbb
 Z}$}/n\mbox{${\mathbb
 Z}$}$ with non--empty color
classes, if and only if $n$ does not satisfy any of the following
conditions:
\textcolor{black}{
\begin{enumerate}
\item[(a)] $n$ is a power of $2$.
\item[(b)] $n$ is a prime and the multiplicative order of $2$ is $n-1$.
\item[(b)] $n$ is a prime, the multiplicative order of $2$ is $(n-1)/2$  and $(n-1)/2$ is odd.
\end{enumerate}
}

\label{thm:main} Let $G$ be a finite abelian
group of odd order $n$ and let $c$ be a $3$--coloring of $G$ with
non--empty color classes $A,B,C$. Then $c$ is rainbow--free if and
only if, up to translation, there is a proper subgroup $H<G$ and a
color class, say $A$, such that \textcolor{black}{the following three conditions hold:}
\begin{enumerate}
\item[{\rm (i)}] $A\subseteq H$, and the $3$--coloring induced in $H$ is
rainbow--free,
\item[{\rm (ii)}] \textcolor{black}{both $\widetilde{B}=B\setminus H$ and $\widetilde{C}=C\setminus H$ are
$H$--periodic sets, and}
\item[{\rm (iii)}] $\widetilde{B}=-\widetilde{B}=2\cdot\widetilde{B}$ and $\widetilde{C}=-\widetilde{C}=2\cdot\widetilde{C}$.
\end{enumerate}

\label{lem:ph}
Let  $A,B$  be  subsets of a finite
 abelian group $G$.
 \textcolor{black}{
 \begin{enumerate}
\item[{\rm (i)}] If $|A|+|B|>|G|$ then $A+B=G$.
\item[{\rm (ii)}] If $|A|+|B|=|G|$ then either $A+B=G$ or there is a subgroup $H$ and $a\in G$ such that both $A$ and $B$ are $H$--periodic and
 $$A+B=G\setminus (a+H).$$
\end{enumerate}}

\label{prop:prime} \textcolor{black}{Let $G$ be a
 group of prime order $p$ and let $c$ be a
$3$--coloring of $G$ with nonempty color classes $A,B,C$. Then $c$
is rainbow--free if and only if, $p\in {\mathcal P}_1$ and, up to
translation, there is a color class, say $A$, such that:}
\begin{enumerate}
\item[{\rm (i)}] \textcolor{black}{$A=\{0\}$,}
\item[{\rm (ii)}] \textcolor{black}{$2\cdot B=B=-B$ and $2\cdot
C=C=-C$.}
\end{enumerate}

\label{lem:onecoset}
\textcolor{black}{If $A$ is contained in a single coset of a proper
subgroup $H'<G$ and $|A|>1$, then the coloring is $H$--regular for some proper subgroup  $H<G$.}

\label{lem:a=b=3}
 \textcolor{black}{If
$|A|=|B|=3$ and $|A+B|=6$, then the coloring is $H$--regular  for some $H<G$.}

\label{lem:almost_p}
Assume that $4\le |A|\le |B|\le |C|$. \textcolor{black}{If $A$ and $B$
are almost--progressions with the same difference $d$, then the coloring is $H$--regular  for some $H<G$.}

\label{lem:periodic}
\textcolor{black}{If the three color classes $A,B,$ and $C$ are
$K$--periodic for some subgroup $K<G$, then the coloring is $H$--regular
for some $H<G$.}

\label{lem:qp}
\textcolor{black}{If $A=A_0\cup A_1$ and $B=B_0\cup B_1$ are
 $K$--quasiperiodic decompositions of $A$ and $B$
with  $K$ a nontrivial proper subgroup of $G$,
 then the coloring is $H$--regular for some $H<G$.}

\label{lem:A+Bperiodic}
If $A+B$ is \textcolor{black}{$K$}--periodic for some proper nontrivial subgroup \textcolor{black}{$K$} of
$G$, \textcolor{black}{then the coloring is $H$--regular for some subgroup $H<G$. }

\label{lem:aqp}
If $A$ and $B$ are almost $H$--quasiperiodic for some proper
nontrivial subgroup $H<G$, \textcolor{black}{then the coloring is $H'$--regular for some proper subgroup $H'<G$.}

\label{prop:ifmain}  Let $\{ A,B,C\}$ be
a coloring of an abelian group $G$  of odd order. If
there is a proper subgroup $H$ of $G$ and a color class, say $A$,
such that \textcolor{black}{the three following conditions hold:}
\begin{enumerate}
\item[{\rm (i)}]  $A\subseteq H$, and the $3$--coloring induced in $H$ is
rainbow--free,
\item[{\rm (ii)}] \textcolor{black}{both $\widetilde{B}=B\setminus H$ and $\widetilde{C}=C\setminus H$ are
$H$--periodic sets, and}
\item[{\rm (iii)}]  $\widetilde{B}=-\widetilde{B}=2\widetilde{B}$ and
$\widetilde{C}=-\widetilde{C}=2\widetilde{C}$.
\end{enumerate}
\textcolor{black}{Then the $3$-coloring is
rainbow--free.}

\label{prop:onlyif} \textcolor{black}{Let $\{ A,B,C\}$ be
a rainbow--free coloring of an abelian group $G$  of odd order. }

\textcolor{black}{There is a proper subgroup $H$ of $G$ and a color class, say $A$,
such that  the three following conditions hold:}
\begin{enumerate}
\item[{\rm (i)}]  $A\subseteq H$, and the $3$--coloring induced in $H$ is
rainbow--free,
\item[{\rm (ii)}] \textcolor{black}{both $\widetilde{B}=B\setminus H$ and $\widetilde{C}=C\setminus H$ are
$H$--periodic sets, and}
\item[{\rm (iii)}]  $\widetilde{B}=-\widetilde{B}=2\widetilde{B}$ and
$\widetilde{C}=-\widetilde{C}=2\widetilde{C}$.
\end{enumerate}

The proof is by induction on the number of  (not
necessarily distinct) primes dividing $n=|G|$. If $n$ is prime, the
statement holds by   Proposition~\ref{prop:prime}.
 \textcolor{black}{We assume} that Theorem~\ref{thm:main} holds
for any group of order a proper divisor of $n=|G|$,
\textcolor{black}{ so that we can use the results in
Section~\ref{sec:local}.}

\textcolor{black}{We first note the following remark.}

\begin{remark}\label{obs:basic}
\textcolor{black}{ For any pair of distinct color classes $X,Y\in
\{A,B,C\}$ we have  $$|X+Y|\le |X|+|Y|.$$ }
\end{remark}

\begin{proof}
\textcolor{black}{Suppose on the contrary that $|X+Y|\ge |X|+|Y|+1$ for some
distinct color classes $X,Y\in \{ A,B,C\}$. Since $n=|G|$ is odd, we have $|2\cdot
Z|=|Z|$ (where $Z$ is the remaining color class). It follows from
the condition $|X+Y|\ge |X|+|Y|+1$ that $(X+Y)\cap (2\cdot Z)\neq \emptyset$,
which implies that there is a rainbow $3$--term arithmetic progression. \qed}

